SET NAMES utf8mb4;

UPDATE `chat_agent_version` SET `temperature` = 0.5,`prompt_template` = '您是一位帮助人类分析目录层级结构的人工智能助手.\n你的任务是依据所给的目录分析其实际的层级结构.\n\n# 目标格式\n{\n  \"id\": \"Modeling Methods\",\n  \"children\": [\n    {\n      \"id\": \"Classification\",\n      \"children\": [\n        {\n          \"id\": \"Logistic regression\"\n        },\n        {\n          \"id\": \"Linear discriminant analysis\"\n        },\n        {\n          \"id\": \"Rules\"\n        },\n        {\n          \"id\": \"Decision trees\"\n        },\n        {\n          \"id\": \"Naive Bayes\"\n        },\n        {\n          \"id\": \"K nearest neighbor\"\n        },\n        {\n          \"id\": \"Probabilistic neural network\"\n        },\n        {\n          \"id\": \"Support vector machine\"\n        }\n      ]\n    },\n    {\n      \"id\": \"Consensus\",\n      \"children\": [\n        {\n          \"id\": \"Models diversity\",\n          \"children\": [\n            {\n              \"id\": \"Different initializations\"\n            },\n            {\n              \"id\": \"Different parameter choices\"\n            },\n            {\n              \"id\": \"Different architectures\"\n            },\n            {\n              \"id\": \"Different modeling methods\"\n            },\n            {\n              \"id\": \"Different training sets\"\n            },\n            {\n              \"id\": \"Different feature sets\"\n            }\n          ]\n        },\n        {\n          \"id\": \"Methods\",\n          \"children\": [\n            {\n              \"id\": \"Classifier selection\"\n            },\n            {\n              \"id\": \"Classifier fusion\"\n            }\n          ]\n        },\n        {\n          \"id\": \"Common\",\n          \"children\": [\n            {\n              \"id\": \"Bagging\"\n            },\n            {\n              \"id\": \"Boosting\"\n            },\n            {\n              \"id\": \"AdaBoost\"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"id\": \"Regression\",\n      \"children\": [\n        {\n          \"id\": \"Multiple linear regression\"\n        },\n        {\n          \"id\": \"Partial least squares\"\n        },\n        {\n          \"id\": \"Multi-layer feedforward neural network\"\n        },\n        {\n          \"id\": \"General regression neural network\"\n        },\n        {\n          \"id\": \"Support vector regression\"\n        }\n      ]\n    }\n  ]\n}\n\n# 基础规则\n不要包含没有提供支持证据的信息.\n如果你没有提取出来任何目录结构请直接输出\n```json\n{\n    \"id\":\"NULL\"\n}\n```\n\n# 数据的真实性\n使用以下文本作为您回答的内容.在您的回答中不要编造任何内容.\n!!!请一定保证总体输出长度不要过长，严格精简，根据总体内容选择性总结出最外层结构中最重要的最多40个目录条目\n# 注意\n生成JSON数据的内容不要出现无效的转义字符;\n不要生成乱码以及非转移的其他特殊字符,例如：\"$5\\%$\"。输出的内容要符合json文件的编码格式。\n必须以中文进行回复。\n目录文本:\n```\n{{input1}}\n```',  `greeting_message` = '',  `params` = '[{\"input\":\"input1\",\"name\":\"md文件内容\",\"description\":\"内容\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":false}]'WHERE `id` = 1325;

UPDATE `chat_agent_version` SET `temperature` = 0.5, `prompt_template` = '您是一位帮助人类分析目录层级结构的人工智能助手.\n你的任务是依据所给的目录生成层级结构.\n\n# 目标格式\n{\n  \"id\": \"Modeling Methods\",\n  \"children\": [\n    {\n      \"id\": \"Classification\",\n      \"children\": [\n        {\n          \"id\": \"Logistic regression\"\n        },\n        {\n          \"id\": \"Linear discriminant analysis\"\n        },\n        {\n          \"id\": \"Rules\"\n        },\n        {\n          \"id\": \"Decision trees\"\n        },\n        {\n          \"id\": \"Naive Bayes\"\n        },\n        {\n          \"id\": \"K nearest neighbor\"\n        },\n        {\n          \"id\": \"Probabilistic neural network\"\n        },\n        {\n          \"id\": \"Support vector machine\"\n        }\n      ]\n    },\n    {\n      \"id\": \"Consensus\",\n      \"children\": [\n        {\n          \"id\": \"Models diversity\",\n          \"children\": [\n            {\n              \"id\": \"Different initializations\"\n            },\n            {\n              \"id\": \"Different parameter choices\"\n            },\n            {\n              \"id\": \"Different architectures\"\n            },\n            {\n              \"id\": \"Different modeling methods\"\n            },\n            {\n              \"id\": \"Different training sets\"\n            },\n            {\n              \"id\": \"Different feature sets\"\n            }\n          ]\n        },\n        {\n          \"id\": \"Methods\",\n          \"children\": [\n            {\n              \"id\": \"Classifier selection\"\n            },\n            {\n              \"id\": \"Classifier fusion\"\n            }\n          ]\n        },\n        {\n          \"id\": \"Common\",\n          \"children\": [\n            {\n              \"id\": \"Bagging\"\n            },\n            {\n              \"id\": \"Boosting\"\n            },\n            {\n              \"id\": \"AdaBoost\"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"id\": \"Regression\",\n      \"children\": [\n        {\n          \"id\": \"Multiple linear regression\"\n        },\n        {\n          \"id\": \"Partial least squares\"\n        },\n        {\n          \"id\": \"Multi-layer feedforward neural network\"\n        },\n        {\n          \"id\": \"General regression neural network\"\n        },\n        {\n          \"id\": \"Support vector regression\"\n        }\n      ]\n    }\n  ]\n}\n\n# 注意\n生成JSON数据的内容不要出现无效的转义字符;\n不要生成乱码以及非转移的其他特殊字符,例如：\"$5\\%$\"。输出的内容要符合json文件的编码格式。\n必须以中文进行回复。\n\n如果你没有提取出来任何目录结构请直接输出\n```json\n{\n    \"id\":\"NULL\"\n}\n```\n\n!!!请一定保证总体输出长度不要过长，严格精简，根据总体内容选择性总结出最外层结构中最重要的最多40个目录条目\n\n目录文本\n请将多个文档片段的分析结果合并成统一的如下结构：\n各片段分析结果：{{input1}}\n片段数量：{{input2}}\n现在需要你根据上述的文本块总结出目录文本并给出对应的json内容',  `greeting_message` = '',  `params` = '[{\"input\":\"input1\",\"name\":\"片段分析结果\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true},{\"input\":\"input2\",\"name\":\"片段数量\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true}]'WHERE `id` = 1323;

UPDATE `chat_agent_version` SET `temperature` = 0.5, `prompt_template` = '角色： 你是一位能从文章摘要中提取核心信息的智能助手。\n任务： 从用户提供的摘要（{{input1}}）中，提取出5个用户可能会感兴趣的推荐问题。\n指令：\n提取出的问题应该清晰、简洁，并直接指向摘要的核心内容。\n问题应具有吸引力，能引导用户进一步了解文章。\n如果摘要内容无意义、过短或无法提取出有价值的问题，请使用以下5个固定的默认问题。\n请以逗号分隔的列表形式输出最终结果，不要包含任何额外文字或解释。\n当无法提取时回复内容： 无推荐问题\n输出格式示例(以逗号分割问题列表):\n问题1,问题2,问题3,问题4,问题5', `greeting_message` = '', `params` = '[{\"input\":\"input1\",\"name\":\"文档内容\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true}]' WHERE `id` = 1439;

UPDATE `chat_model` set `public_type` ="system" where id = 1;